import { useEffect, useRef, useState } from "react";
import { Pressable, StyleSheet, Text } from "react-native";
import type { PressableProps, StyleProp, TextStyle, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface CopyButtonProps extends Omit<PressableProps, "style" | "children" | "onPress"> {
  value: string;
  label?: string;
  /**
   * Writes the text to the clipboard. React Native has no built-in clipboard, so pass the one your app uses, for example
   * `(text) => Clipboard.setStringAsync(text)` from expo-clipboard.
   */
  copy: (value: string) => void | Promise<void>;
  iconOnly?: boolean;
  variant?: "outline" | "plain";
  onCopied?: () => void;
  style?: StyleProp<ViewStyle>;
  /** Extend the inner, named parts of the copy button: icon or label. The React Native counterpart of `classNames`. */
  styles?: {
    icon?: StyleProp<TextStyle>;
    label?: StyleProp<TextStyle>;
  };
}

export function CopyButton({ value, label = "Copy", copy, iconOnly = false, variant = "outline", disabled, onCopied, style, styles: parts, ...props }: CopyButtonProps) {
  const tokens = useTokens();
  const [copied, setCopied] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  useEffect(() => () => clearTimeout(timer.current), []);

  async function onPress() {
    try {
      await copy(value);
      setCopied(true);
      onCopied?.();
      clearTimeout(timer.current);
      timer.current = setTimeout(() => setCopied(false), 1600);
    } catch {
      setCopied(false);
    }
  }

  return (
    <Pressable
      {...props}
      accessibilityRole="button"
      accessibilityLabel={copied ? "Copied" : label}
      disabled={disabled}
      onPress={onPress}
      style={({ pressed }) => [
        local.root,
        {
          minHeight: metrics.controlHeight.sm,
          borderColor: variant === "outline" ? tokens.border : "transparent",
          backgroundColor: pressed ? tokens.surfaceMuted : variant === "outline" ? tokens.surface : "transparent",
          opacity: disabled ? 0.5 : 1,
        },
        style,
      ]}
    >
      <Text style={[{ color: copied ? tokens.success : tokens.textSecondary, fontSize: 14 }, parts?.icon]}>{copied ? "✓" : "⧉"}</Text>
      {iconOnly ? null : <Text style={[{ color: tokens.foreground, fontSize: metrics.text.sm, fontWeight: "500" }, parts?.label]}>{copied ? "Copied" : label}</Text>}
    </Pressable>
  );
}

const local = StyleSheet.create({
  root: { flexDirection: "row", alignItems: "center", alignSelf: "flex-start", gap: 6, paddingHorizontal: metrics.space[3], borderWidth: 1, borderRadius: metrics.radiusControl },
});

export default CopyButton;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
  /** Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4. */
  series: [string, string, string, string];
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
  series: ["#1f7dcf", "#7128a5", "#e58f00", "#009e84"],
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
  series: ["#55adff", "#9c37be", "#e66e00", "#00a861"],
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
